class PushRequestController {
  constructor(private repo: PushRepo, private queue: PushQueue) {}

  async submit(input: { userId: string; title: string; body: string }) {
    const notice = await this.repo.insert({
      userId: input.userId,
      title: input.title,
      body: input.body,
      status: 'queued'
    });
    await this.queue.add({ noticeId: notice.id });
    return { noticeId: notice.id };
  }
}

class PushWorker {
  constructor(
    private repo: PushRepo,
    private preferences: PreferenceStore,
    private devices: DeviceStore,
    private gateway: PushGateway,
    private callbacks: CallbackQueue
  ) {}

  async handle(job: { noticeId: string }) {
    const notice = await this.repo.get(job.noticeId);
    const preferences = await this.preferences.get(notice.userId);
    if (!preferences.pushEnabled) {
      await this.finish(notice.id, 'suppressed');
      return;
    }

    const tokens = await this.devices.activeTokens(notice.userId);
    if (tokens.length === 0) {
      await this.finish(notice.id, 'no_devices');
      return;
    }

    const result = await this.gateway.sendMulticast(tokens, {
      title: notice.title,
      body: notice.body,
      data: { noticeId: notice.id }
    });
    const status = result.acceptedIds.length > 0 ? 'sent' : 'failed';
    await this.finish(notice.id, status, result.acceptedIds, result.rejectedIds);
  }

  private async finish(
    noticeId: string,
    status: string,
    acceptedIds: string[] = [],
    rejectedIds: string[] = []
  ) {
    await this.repo.setStatus(noticeId, status);
    await this.callbacks.add({ noticeId, status, acceptedIds, rejectedIds });
  }
}

class PushCallbackWorker {
  constructor(private sink: PushCallbackSink) {}

  async handle(job: { noticeId: string; status: string; acceptedIds: string[]; rejectedIds: string[] }) {
    await this.sink.deliver({
      noticeId: job.noticeId,
      status: job.status,
      acceptedDeviceIds: job.acceptedIds,
      rejectedDeviceIds: job.rejectedIds
    });
  }
}
